/**
 * Génération du ZPL final pour étiquette produit Zebra (PRODUCT_LABEL).
 *
 * On part d'un template ZPL contenant des placeholders `{{KEY}}` et on les
 * remplace par les vraies données issues de la fiche technique + saisie opérateur.
 *
 * Champs variables :
 *  - {{DESIGNATION}}        : libellé carton (erp_label / product_name + format)
 *  - {{BARCODE}}            : EAN/code-barre (chiffres uniquement)
 *  - {{POIDS_NET}}          : ex "2.46 kg"
 *  - {{INGREDIENTS}}        : liste INCO complète, nettoyée et sans HTML
 *  - {{INGR_L1..L20}}       : lignes ingrédients de secours
 *  - {{ALLERGENES}}         : conservé pour anciens templates (vide)
 *  - {{TRACES}} / L1-L2     : mention "Peut contenir des traces"
 *  - {{NUTRI_L1..L4}}       : 4 lignes nutrition / 100g
 *  - {{LOT}}                : numéro de lot (sans le "L" de préfixe — le L est dessiné séparément)
 *  - {{DDM_J}}              : jour de l'année de la DDM (3 chiffres)
 *  - {{DDM_YY}}             : 2 derniers chiffres de l'année de la DDM
 *  - {{QTY}}                : quantité (^PQ)
 */

import { removeAccents, splitIntoLines } from './zebraLabelExport';

/**
 * Découpe un texte en lignes pleines en cassant uniquement sur les espaces (pas sur les virgules).
 * Permet de remplir au maximum la largeur disponible de l'étiquette.
 */
function fillLines(text: string, maxLength: number, maxLines: number): string[] {
  const clean = removeAccents((text || '').trim()).replace(/\s+/g, ' ');
  const lines: string[] = [];
  let remaining = clean;
  while (remaining.length > 0 && lines.length < maxLines) {
    if (remaining.length <= maxLength) {
      lines.push(remaining);
      remaining = '';
      break;
    }
    let cut = remaining.lastIndexOf(' ', maxLength);
    if (cut < Math.floor(maxLength * 0.5)) cut = maxLength;
    lines.push(remaining.substring(0, cut).trim());
    remaining = remaining.substring(cut).trim();
  }
  while (lines.length < maxLines) lines.push('');
  return lines;
}

export interface ZplLabelData {
  designation: string;
  barcode: string | null;
  netWeight: number | null;
  netWeightUnit: string | null;
  ingredientsHtml: string | null;
  allergens: string | null;        // allergènes présents (texte)
  traces: string | null;           // traces (texte)
  nutrition: {
    energyKj?: number; energyKcal?: number;
    fat?: number; saturatedFat?: number;
    carbohydrates?: number; sugars?: number;
    fiber?: number; protein?: number; salt?: number;
  } | null;
  lotNumber: string;               // ex "L00326" (le préfixe L est inclus)
  ddm: string;                     // ISO yyyy-mm-dd
  quantity: number;
  storageInstructions?: string | null;
  thawingInstructions?: string | null;
}

function cleanHtml(html: string | null): string {
  if (!html) return '';
  return html
    // Met les allergènes en MAJUSCULES (équivalent du gras, conforme INCO 1169/2011 pour impression thermique)
    .replace(/<(?:strong|b)\b[^>]*>([\s\S]*?)<\/(?:strong|b)>/gi, (_, inner) => String(inner).toUpperCase())
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/\s+/g, ' ')
    .trim();
}

function zplSafe(text: string): string {
  return removeAccents(text)
    .replace(/[\^~\\]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function extractTracesFromStatement(statement: string | null): string {
  if (!statement) return '';
  const normalized = zplSafe(statement);
  const match = normalized.match(/(?:peut contenir(?: des?)?|traces?)\s*(?:traces?)?\s*(?:eventuelles?)?\s*(?:de|d')?\s*[:\-]\s*(.+)$/i);
  return match ? match[1].trim().replace(/[.\s]+$/, '') : '';
}

function normalizeTraceValue(value: string | null): string {
  if (!value) return '';
  return zplSafe(value)
    .replace(/^peut contenir(?: des?)?\s+traces?\s*(?:de|d')?\s*[:\-]?\s*/i, '')
    .replace(/^traces?\s*(?:eventuelles?)?\s*(?:de|d')?\s*[:\-]?\s*/i, '')
    .replace(/[.\s]+$/, '')
    .trim();
}

function computeJulianDay(iso: string): { j: string; yy: string; fr: string } {
  const d = new Date(iso + 'T00:00:00');
  if (isNaN(d.getTime())) return { j: '', yy: '', fr: '' };
  const start = new Date(d.getFullYear(), 0, 0);
  const dayOfYear = Math.floor((d.getTime() - start.getTime()) / 86400000);
  const dd = String(d.getDate()).padStart(2, '0');
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  const yyyy = String(d.getFullYear());
  return {
    j: String(dayOfYear).padStart(3, '0'),
    yy: yyyy.slice(-2),
    fr: `${dd}/${mm}/${yyyy}`,
  };
}

function formatNetWeight(w: number | null, unit: string | null): string {
  if (!w) return '';
  return `${w} ${unit || 'kg'}`;
}

function formatNutrition(n: ZplLabelData['nutrition']): [string, string, string, string] {
  if (!n) return ['', '', '', ''];
  return [
    `Energie ${Math.round(n.energyKj ?? 0)} kJ / ${Math.round(n.energyKcal ?? 0)} kcal`,
    `Lipides ${(n.fat ?? 0).toFixed(1)} g dont satures ${(n.saturatedFat ?? 0).toFixed(1)} g`,
    `Glucides ${(n.carbohydrates ?? 0).toFixed(1)} g dont sucres ${(n.sugars ?? 0).toFixed(1)} g`,
    `Fibres ${(n.fiber ?? 0).toFixed(1)} g - Proteines ${(n.protein ?? 0).toFixed(1)} g - Sel ${(n.salt ?? 0).toFixed(2)} g`,
  ].map(removeAccents) as [string, string, string, string];
}

/**
 * Remplit le template ZPL avec les données et retourne le ZPL prêt à imprimer.
 * Le template doit utiliser des placeholders au format {{KEY}}.
 */
export function fillZplTemplate(template: string, data: ZplLabelData): string {
  // Police 9pt réelle à 300 dpi : hauteur ≈ 37 dots, largeur ≈ 22 dots.
  // Largeur dispo 740 dots ≈ 6cm. On utilise ^FB (auto-wrap natif Zebra)
  // qui calcule la vraie largeur des caractères au lieu d'estimer manuellement.
  // Compactage : on doit tenir tout le contenu dans ~6cm de hauteur sous la ligne du logo.
  const FONT_H = 26;
  const FONT_W = 16;
  const FB_WIDTH = 740;          // largeur de wrap en dots ≈ 6cm
  const LINE_GAP = 28;           // espacement vertical entre lignes (compacté)
  const SECTION_GAP = 0;         // plus aucun espace entre blocs
  // Estimation du nb de lignes : largeur moyenne d'un caractère ≈ FONT_W * 0.55
  const CHARS_PER_LINE = Math.floor(FB_WIDTH / (FONT_W * 0.55));

  const estimateLines = (text: string): number => {
    if (!text) return 0;
    // Découpe en respectant les espaces pour estimer plus juste
    let lines = 0;
    let remaining = text;
    while (remaining.length > 0) {
      if (remaining.length <= CHARS_PER_LINE) { lines++; break; }
      let cut = remaining.lastIndexOf(' ', CHARS_PER_LINE);
      if (cut < CHARS_PER_LINE * 0.5) cut = CHARS_PER_LINE;
      lines++;
      remaining = remaining.substring(cut).trim();
    }
    return Math.max(1, lines);
  };

  const ingredientsText = zplSafe(cleanHtml(data.ingredientsHtml));
  const nutri = formatNutrition(data.nutrition);
  const { j, yy, fr } = computeJulianDay(data.ddm);

  const storageText = zplSafe([data.storageInstructions, data.thawingInstructions]
    .filter(Boolean)
    .join(' — ') || 'A conserver dans le sachet a temperature ambiante de preference inferieure a 30 C');

  const lotValue = data.lotNumber.replace(/^L/i, '');

  const traceSource = normalizeTraceValue(data.traces) || extractTracesFromStatement(data.allergens);
  const tracesText = traceSource ? `Peut contenir des traces : ${traceSource}` : '';

  // Construction dynamique du bloc gauche avec ^FB pour exploiter toute la largeur.
  const bodyParts: string[] = [];
  // ^FT positionne une baseline (pas le haut du texte), ce qui rendait le bloc visuellement trop haut sur Zebra.
  // On utilise ^FO pour ancrer le haut réel du bloc sous la ligne horizontale du logo.
  let y = 156;

  const addBlock = (text: string, maxLines: number) => {
    if (!text) return;
    const lines = Math.min(maxLines, estimateLines(text));
    bodyParts.push(`^FO18,${y}^A0N,${FONT_H},${FONT_W}^FB${FB_WIDTH},${lines},0,L,0^FH\\^FD${text}^FS`);
    y += lines * LINE_GAP;
  };

  // Titre Ingrédients (compact)
  bodyParts.push(`^FO18,${y}^A0N,22,18^FH\\^FDIngredients :^FS`);
  y += 26;
  addBlock(ingredientsText, 14);
  if (tracesText) {
    y += SECTION_GAP;
    addBlock(tracesText, 3);
  }
  y += SECTION_GAP;
  addBlock(storageText, 3);
  y += SECTION_GAP;
  bodyParts.push(`^FO18,${y}^A0N,${FONT_H},${FONT_W}^FH\\^FDValeurs nutritionnelles pour 100g :^FS`);
  y += LINE_GAP;
  for (const line of nutri) {
    bodyParts.push(`^FO18,${y}^A0N,${FONT_H},${FONT_W}^FH\\^FD${line}^FS`);
    y += LINE_GAP;
  }

  const body = bodyParts.join('\n');

  // Compatibilité anciens templates (placeholders fixes)
  const ingrLinesCompat = fillLines(ingredientsText, 33, 24);
  const tracesLinesCompat = tracesText ? fillLines(tracesText, 33, 3) : [];
  const storageLinesCompat = fillLines(storageText, 33, 3);

  const replacements: Record<string, string> = {
    DESIGNATION: zplSafe(data.designation || ''),
    BARCODE: (data.barcode || '').replace(/\D/g, ''),
    POIDS_NET: zplSafe(formatNetWeight(data.netWeight, data.netWeightUnit)),
    INGREDIENTS: ingredientsText,
    ALLERGENES: '',
    TRACES: tracesText,
    BODY: body,
    LOT: lotValue,
    DDM_J: j,
    DDM_YY: yy,
    DDM_FR: fr,
    QTY: String(Math.max(1, data.quantity)),
  };

  // Compatibilité avec anciens templates utilisant des placeholders fixes.
  for (let i = 1; i <= 24; i++) replacements[`INGR_L${i}`] = ingrLinesCompat[i - 1] || '';
  replacements.TRACES_L1 = tracesLinesCompat[0] || '';
  replacements.TRACES_L2 = tracesLinesCompat[1] || '';
  replacements.STORAGE_L1 = storageLinesCompat[0] || '';
  replacements.STORAGE_L2 = storageLinesCompat[1] || '';
  replacements.NUTRI_L1 = nutri[0];
  replacements.NUTRI_L2 = nutri[1];
  replacements.NUTRI_L3 = nutri[2];
  replacements.NUTRI_L4 = nutri[3];

  return template.replace(/\{\{(\w+)\}\}/g, (_, k) => replacements[k] ?? '');
}

